1	import { decodeCanonical, hashDomain } from "@ts-drp/canonical";
2	import type { GenerationRef } from "@ts-drp/storage";
3	
4	import { type DetachedClosureCandidate, inspectTrustClosure } from "./anchor-trust.js";
5	
6	const DIGEST_HEX = /^[0-9a-f]{64}$/u;
7	
8	export type CreatorTrustAdvanceRejection =
9		| "BYTE_REPLAY"
10		| "EPOCH_EQUIVOCATION"
11		| "EPOCH_GAP"
12		| "ROLLBACK"
13		| "TRUST_CLOSURE_INVALID";
14	
15	export type CreatorTrustAdvanceResult =
16		| Readonly<{ readonly kind: "successor"; readonly ok: true }>
17		| Readonly<{ readonly ok: false; readonly reason: CreatorTrustAdvanceRejection }>;
18	
19	export interface DetachedTrustClosure {
20		readonly candidates: readonly DetachedClosureCandidate[];
21		readonly closure: readonly GenerationRef[];
22	}
23	
24	export interface InspectCreatorTrustAdvanceInput {
25		readonly current: DetachedTrustClosure;
26		readonly proofRefs: readonly GenerationRef[];
27		readonly proposed: DetachedTrustClosure;
28	}
29	
30	interface TrustRecord extends Readonly<Record<string, unknown>> {
31		readonly currentAnchorDigest: string;
32		readonly currentEpoch: number;
33		readonly exactCanonicalCurrentAnchorPreimageBytes: Uint8Array;
34		readonly exactCanonicalProfileBytes: Uint8Array;
35		readonly exactCanonicalSignerSetBytes: Uint8Array;
36		readonly genesisAnchorDigest: string;
37		readonly objectId: string;
38		readonly profileId: string;
39		readonly quorum: number;
40		readonly version: number;
41	}
42	
43	function rejected(reason: CreatorTrustAdvanceRejection): CreatorTrustAdvanceResult {
44		return Object.freeze({ ok: false as const, reason });
45	}
46	
47	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
48		if (left.byteLength !== right.byteLength) return false;
49		for (let index = 0; index < left.byteLength; index += 1) {
50			if (left[index] !== right[index]) return false;
51		}
52		return true;
53	}
54	
55	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
56		return left.byteLength === right.byteLength && left.digest === right.digest;
57	}
58	
59	function compareRef(left: GenerationRef, right: GenerationRef): number {
60		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
61	}
62	
63	function copyRef(value: unknown): GenerationRef | undefined {
64		if (value === null || typeof value !== "object" || Array.isArray(value)) return undefined;
65		const record = value as Readonly<Record<string, unknown>>;
66		if (
67			Object.keys(record).length !== 2 ||
68			!Object.hasOwn(record, "byteLength") ||
69			!Object.hasOwn(record, "digest") ||
70			typeof record.byteLength !== "number" ||
71			!Number.isSafeInteger(record.byteLength) ||
72			record.byteLength < 0 ||
73			typeof record.digest !== "string" ||
74			!DIGEST_HEX.test(record.digest)
75		)
76			return undefined;
77		return Object.freeze({ byteLength: record.byteLength, digest: record.digest }) as GenerationRef;
78	}
79	
80	function copyProofRefs(value: unknown): readonly [GenerationRef, GenerationRef] | undefined {
81		if (!Array.isArray(value) || value.length !== 2) return undefined;
82		const first = copyRef(value[0]);
83		const second = copyRef(value[1]);
84		if (first === undefined || second === undefined || first.digest === second.digest) return undefined;
85		return Object.freeze([first, second]);
86	}
87	
88	function exactCombinedClosure(
89		current: readonly GenerationRef[],
90		currentTrustRef: GenerationRef,
91		proofRefs: readonly [GenerationRef, GenerationRef],
92		successorTrustRef: GenerationRef
93	): readonly GenerationRef[] | undefined {
94		const retained = current.filter((ref) => ref.digest !== currentTrustRef.digest);
95		if (retained.length !== current.length - 1) return undefined;
96		const combined = [...retained, successorTrustRef, ...proofRefs];
97		if (new Set(combined.map(({ digest }) => digest)).size !== combined.length) return undefined;
98		return Object.freeze([...combined].sort(compareRef));
99	}
100	
101	function bytesHex(bytes: Uint8Array): string {
102		let value = "";
103		for (const byte of bytes) value += byte.toString(16).padStart(2, "0");
104		return value;
105	}
106	
107	function decodeTrust(bytes: Uint8Array): TrustRecord | undefined {
108		try {
109			const value = decodeCanonical(bytes);
110			return value !== null && typeof value === "object" && !Array.isArray(value) ? (value as TrustRecord) : undefined;
111		} catch {
112			return undefined;
113		}
114	}
115	
116	function validSuccessorBinding(current: TrustRecord, successor: TrustRecord): boolean {
117		try {
118			if (
119				successor.version !== 1 ||
120				successor.objectId !== current.objectId ||
121				successor.genesisAnchorDigest !== current.genesisAnchorDigest ||
122				successor.profileId !== current.profileId ||
123				successor.quorum !== current.quorum ||
124				!(successor.exactCanonicalProfileBytes instanceof Uint8Array) ||
125				!(current.exactCanonicalProfileBytes instanceof Uint8Array) ||
126				!sameBytes(successor.exactCanonicalProfileBytes, current.exactCanonicalProfileBytes) ||
127				!(successor.exactCanonicalSignerSetBytes instanceof Uint8Array) ||
128				!(current.exactCanonicalSignerSetBytes instanceof Uint8Array) ||
129				!sameBytes(successor.exactCanonicalSignerSetBytes, current.exactCanonicalSignerSetBytes) ||
130				!(successor.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array)
131			)
132				return false;
133			const anchorValue = decodeCanonical(successor.exactCanonicalCurrentAnchorPreimageBytes);
134			if (anchorValue === null || typeof anchorValue !== "object" || Array.isArray(anchorValue)) return false;
135			const anchor = anchorValue as Readonly<Record<string, unknown>>;
136			return (
137				anchor.objectId === current.objectId &&
138				anchor.epoch === successor.currentEpoch &&
139				anchor.previousAnchor === current.currentAnchorDigest &&
140				successor.currentAnchorDigest ===
141					bytesHex(hashDomain("ts-drp/epoch-anchor/v3", successor.exactCanonicalCurrentAnchorPreimageBytes))
142			);
143		} catch {
144			return false;
145		}
146	}
147	
148	/**
149	 * Classifies one exact creator-trust successor closure without writing storage.
150	 * @param input - Detached current/proposed closures and the certified CutValue/QC refs.
151	 * @returns The closed advancement verdict.
152	 */
153	export function inspectCreatorTrustAdvance(input: InspectCreatorTrustAdvanceInput): CreatorTrustAdvanceResult {
154		try {
155			if (input === null || typeof input !== "object" || Array.isArray(input)) return rejected("TRUST_CLOSURE_INVALID");
156			const currentClosure = Object.freeze([...input.current.closure].sort(compareRef));
157			const current = inspectTrustClosure({ candidates: input.current.candidates, closure: currentClosure });
158			const proposed = inspectTrustClosure(input.proposed);
159			const proofRefs = copyProofRefs(input.proofRefs);
160			if (!current.ok || !proposed.ok || proofRefs === undefined) return rejected("TRUST_CLOSURE_INVALID");
161			const combined = exactCombinedClosure(currentClosure, current.trustRef, proofRefs, proposed.trustRef);
162			if (
163				combined === undefined ||
164				combined.length !== input.proposed.closure.length ||
165				combined.some((ref, index) => !sameRef(ref, input.proposed.closure[index] as GenerationRef))
166			)
167				return rejected("TRUST_CLOSURE_INVALID");
168			if (sameBytes(current.exactCanonicalTrustStateRecordBytes, proposed.exactCanonicalTrustStateRecordBytes)) {
169				return rejected("BYTE_REPLAY");
170			}
171			const currentRecord = decodeTrust(current.exactCanonicalTrustStateRecordBytes);
172			const proposedRecord = decodeTrust(proposed.exactCanonicalTrustStateRecordBytes);
173			if (currentRecord === undefined || proposedRecord === undefined || typeof currentRecord.currentEpoch !== "number") {
174				return rejected("TRUST_CLOSURE_INVALID");
175			}
176			if (proposedRecord.currentEpoch === currentRecord.currentEpoch) return rejected("EPOCH_EQUIVOCATION");
177			if (typeof proposedRecord.currentEpoch !== "number" || proposedRecord.currentEpoch < currentRecord.currentEpoch) {
178				return rejected("ROLLBACK");
179			}
180			if (proposedRecord.currentEpoch !== currentRecord.currentEpoch + 1) return rejected("EPOCH_GAP");
181			if (!validSuccessorBinding(currentRecord, proposedRecord)) return rejected("TRUST_CLOSURE_INVALID");
182			return Object.freeze({ kind: "successor" as const, ok: true as const });
183		} catch {
184			return rejected("TRUST_CLOSURE_INVALID");
185		}
186	}

